-- Preserve the unused Prisma/Auth.js tables without exposing them through the -- public Supabase Data API. This migration does not drop or truncate data. create schema if not exists legacy; create schema if not exists private; revoke all on schema legacy from public, anon, authenticated; revoke all on schema private from public, anon, authenticated, service_role;  do $$ declare table_name text; begin   foreach table_name in array array['User','Account','Session','VerificationToken','Game','Product','Order','OrderItem','WishlistItem','Coupon','Review','Testimonial','PaymentEvent','StoreSettings'] loop     if to_regclass(format('public.%I', table_name)) is not null then       execute format('alter table public.%I set schema legacy', table_name);     end if;   end loop; end; $$; revoke all on all tables in schema legacy from public, anon, authenticated, service_role;  -- Move exposed SECURITY DEFINER helpers to a non-exposed schema. The event -- trigger remains attached by function OID when its implementation is moved. do $$ begin   if to_regprocedure('public.rls_auto_enable()') is not null then     execute 'alter function public.rls_auto_enable() set schema private';   end if;   if to_regprocedure('public.handle_new_user()') is not null then     execute 'alter function public.handle_new_user() set schema private';   end if; end; $$; do $$ begin   if to_regprocedure('private.rls_auto_enable()') is not null then     execute 'revoke all on function private.rls_auto_enable() from public, anon, authenticated, service_role';   end if; end; $$;  create table if not exists public.site_settings (   id uuid primary key default gen_random_uuid(),   key text not null unique check (char_length(key) between 1 and 100),   value jsonb not null,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() ); insert into public.site_settings (key, value) select 'storefront', jsonb_build_object(   'storeName', store_name, 'description', description, 'supportEmail', support_email,   'heroBadge', hero_badge, 'heroTitle', hero_title, 'heroHighlight', hero_highlight,   'heroDescription', hero_description, 'heroImage', hero_image ) from public.store_settings where id = 'default' on conflict (key) do nothing; insert into public.site_settings (key, value) values ('storefront', jsonb_build_object(   'storeName', 'NEXA Gaming',   'description', 'Instant game credits, currency, and digital top-ups built for gamers.',   'supportEmail', 'support@example.com', 'heroBadge', 'THE NEXT LEVEL STARTS HERE',   'heroTitle', 'Power up', 'heroHighlight', 'your game.',   'heroDescription', 'Instant game credits, currency, and digital top-ups built for gamers who play to win.',   'heroImage', 'photo-1542751371-adc38448a05e' )) on conflict (key) do nothing; do $$ begin   if to_regclass('public.store_settings') is not null then     execute 'alter table public.store_settings set schema legacy';   end if; end; $$; revoke all on all tables in schema legacy from public, anon, authenticated, service_role; alter table public.site_settings enable row level security; grant select on public.site_settings to anon, authenticated; grant insert, update, delete on public.site_settings to authenticated; create policy "public storefront settings are readable" on public.site_settings for select to anon, authenticated   using (key = 'storefront' or exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins manage site settings" on public.site_settings for all to authenticated   using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())))   with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));  alter table public.orders   add column if not exists order_number text,   add column if not exists coupon_id uuid references public.coupons(id) on delete set null,   add column if not exists updated_at timestamptz not null default now(); alter table public.orders alter column order_number set default ('NEXA-' || upper(substr(gen_random_uuid()::text, 1, 8))); update public.orders set order_number = 'NEXA-' || upper(substr(id::text, 1, 8)) where order_number is null; alter table public.orders alter column order_number set not null; create unique index if not exists orders_order_number_key on public.orders (order_number); create index if not exists orders_coupon_idx on public.orders (coupon_id) where coupon_id is not null;  alter table public.order_items add column if not exists line_total numeric(10,2); update public.order_items set line_total = unit_price * quantity where line_total is null; alter table public.order_items alter column line_total set not null; alter table public.order_items add constraint order_items_line_total_nonnegative check (line_total >= 0);  create table if not exists public.payments (   id uuid primary key default gen_random_uuid(),   order_id uuid not null references public.orders(id) on delete restrict,   provider text not null,   provider_payment_id text,   status text not null default 'INITIATED' check (status in ('INITIATED','PENDING','SUCCEEDED','FAILED','CANCELLED','REFUNDED')),   amount numeric(10,2) not null check (amount >= 0),   currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),   metadata jsonb not null default '{}'::jsonb,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now(),   unique (provider, provider_payment_id) ); create table if not exists public.fulfillments (   id uuid primary key default gen_random_uuid(),   order_id uuid not null references public.orders(id) on delete restrict,   order_item_id uuid references public.order_items(id) on delete set null,   provider text not null default 'manual',   status text not null default 'PENDING' check (status in ('PENDING','PROCESSING','DELIVERED','FAILED','CANCELLED')),   external_reference text,   delivery_data jsonb,   error_message text,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() ); create table if not exists public.coupon_usages (   id uuid primary key default gen_random_uuid(),   coupon_id uuid not null references public.coupons(id) on delete restrict,   user_id uuid not null references auth.users(id) on delete restrict,   order_id uuid not null unique references public.orders(id) on delete restrict,   discount_amount numeric(10,2) not null check (discount_amount >= 0),   created_at timestamptz not null default now(),   unique (coupon_id, user_id) ); create table if not exists public.promo_banners (   id uuid primary key default gen_random_uuid(),   title text not null check (char_length(title) between 2 and 120),   subtitle text not null default '', image_url text, cta_label text, cta_url text,   starts_at timestamptz, ends_at timestamptz,   is_active boolean not null default true, sort_order integer not null default 0,   created_at timestamptz not null default now(), updated_at timestamptz not null default now(),   constraint promo_banners_valid_schedule check (ends_at is null or starts_at is null or ends_at > starts_at) );  create index if not exists payments_order_idx on public.payments (order_id, created_at desc); create index if not exists fulfillments_order_idx on public.fulfillments (order_id, created_at desc); create index if not exists fulfillments_item_idx on public.fulfillments (order_item_id) where order_item_id is not null; create index if not exists coupon_usages_user_idx on public.coupon_usages (user_id, created_at desc); create index if not exists promo_banners_public_order_idx on public.promo_banners (sort_order, starts_at, ends_at) where is_active;  create trigger site_settings_set_updated_at before update on public.site_settings for each row execute function public.set_updated_at(); create trigger orders_set_updated_at before update on public.orders for each row execute function public.set_updated_at(); create trigger payments_set_updated_at before update on public.payments for each row execute function public.set_updated_at(); create trigger fulfillments_set_updated_at before update on public.fulfillments for each row execute function public.set_updated_at(); create trigger promo_banners_set_updated_at before update on public.promo_banners for each row execute function public.set_updated_at();  alter table public.payments enable row level security; alter table public.fulfillments enable row level security; alter table public.coupon_usages enable row level security; alter table public.promo_banners enable row level security; grant select on public.payments, public.fulfillments, public.coupon_usages to authenticated; grant select on public.promo_banners to anon, authenticated; grant insert, update, delete on public.promo_banners to authenticated; create policy "users read own payments" on public.payments for select to authenticated   using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = (select auth.uid()))); create policy "admins manage payments" on public.payments for all to authenticated   using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())))   with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins manage fulfillments" on public.fulfillments for all to authenticated   using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())))   with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "users read own coupon usages" on public.coupon_usages for select to authenticated using ((select auth.uid()) = user_id); create policy "admins read coupon usages" on public.coupon_usages for select to authenticated   using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "active scheduled banners are public" on public.promo_banners for select to anon, authenticated   using (is_active and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at >= now())); create policy "admins manage promo banners" on public.promo_banners for all to authenticated   using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())))   with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));  -- Remove broad insert paths: checkout is the only customer order creator. revoke insert on public.orders, public.order_items from authenticated; drop policy if exists "server checkout creates orders" on public.orders; drop policy if exists "server checkout reads new order id" on public.orders; drop policy if exists "users create own orders" on public.orders; drop policy if exists "server checkout creates order items" on public.order_items; drop policy if exists "users create order items" on public.order_items; drop policy if exists "server checkout reads active products" on public.products; drop policy if exists "server checkout reads active offers" on public.offers;  create or replace function private.create_checkout_order(p_items jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$ declare   v_user_id uuid := (select auth.uid());   v_email text;   v_order_id uuid;   v_subtotal numeric(10,2);   v_discount numeric(10,2);   v_total numeric(10,2); begin   if v_user_id is null then raise exception 'Authentication required' using errcode = '28000'; end if;   if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 50 then     raise exception 'Cart must contain 1 to 50 items' using errcode = '22023';   end if;   if exists (select 1 from jsonb_to_recordset(p_items) as item(slug text, quantity integer)     where item.slug is null or item.slug = '' or item.quantity not between 1 and 50) then     raise exception 'Cart contains invalid items' using errcode = '22023';   end if;   if exists (select 1 from (select sum(item.quantity) quantity from jsonb_to_recordset(p_items) as item(slug text, quantity integer) group by item.slug) q where q.quantity > 50) then     raise exception 'Product quantity exceeds the limit' using errcode = '22023';   end if;   select u.email into v_email from auth.users u where u.id = v_user_id;   if v_email is null then raise exception 'Account email is required' using errcode = '22023'; end if;    with requested as (     select item.slug, sum(item.quantity)::integer quantity     from jsonb_to_recordset(p_items) as item(slug text, quantity integer) group by item.slug   ), priced as (     select p.id, p.name, p.price, requested.quantity, best.offer_id,       coalesce(best.amount, 0)::numeric(10,2) discount_per_unit     from requested join public.products p on p.slug = requested.slug and p.is_active     left join lateral (       select o.id offer_id,         least(p.price, case when o.discount_type = 'percentage' then p.price * o.discount_value / 100 else o.discount_value end) amount       from public.offers o       where o.is_active and o.starts_at <= now() and o.ends_at >= now()         and (o.product_id = p.id or o.game_id = p.game_id or o.category_id = p.category_id)       order by amount desc, o.sort_order, o.ends_at limit 1     ) best on true   ), totals as (     select (select count(*) from requested) requested_count, count(*) product_count,       coalesce(sum(priced.price * priced.quantity),0)::numeric(10,2) subtotal,       coalesce(sum(priced.discount_per_unit * priced.quantity),0)::numeric(10,2) discount     from priced   ), created as (     insert into public.orders (user_id, email, subtotal, discount, total)     select v_user_id, v_email, subtotal, discount, subtotal-discount from totals     where requested_count > 0 and requested_count = product_count returning id   ), items_created as (     insert into public.order_items (order_id, product_id, product_name, quantity, unit_price, line_total, offer_id)     select created.id, priced.id, priced.name, priced.quantity,       greatest(0,priced.price-priced.discount_per_unit)::numeric(10,2),       (greatest(0,priced.price-priced.discount_per_unit)*priced.quantity)::numeric(10,2), priced.offer_id     from created cross join priced returning 1   ), payment_created as (     insert into public.payments (order_id, provider, status, amount, currency)     select created.id, 'pending', 'INITIATED', totals.subtotal-totals.discount, 'USD'     from created cross join totals returning id   )   select created.id, totals.subtotal, totals.discount, totals.subtotal-totals.discount   into v_order_id, v_subtotal, v_discount, v_total from created cross join totals;    if v_order_id is null then raise exception 'One or more cart products are unavailable' using errcode = '22023'; end if;   return jsonb_build_object('id',v_order_id,'subtotal',v_subtotal,'discount',v_discount,'total',v_total); end; $$;  create or replace function private.record_checkout_payment(p_order_id uuid, p_provider text, p_provider_payment_id text) returns void language plpgsql security definer set search_path = '' as $$ begin   if (select auth.uid()) is null then raise exception 'Authentication required' using errcode = '28000'; end if;   if p_provider is null or char_length(p_provider) not between 1 and 80 or p_provider_payment_id is null     or char_length(p_provider_payment_id) not between 1 and 200 then     raise exception 'Invalid payment reference' using errcode = '22023';   end if;   update public.payments payment set provider=p_provider, provider_payment_id=p_provider_payment_id, status='PENDING'   from public.orders order_row   where payment.order_id=p_order_id and payment.order_id=order_row.id     and order_row.user_id=(select auth.uid()) and payment.status='INITIATED';   if not found then raise exception 'Payment session not found for this account' using errcode = '42501'; end if; end; $$;  create or replace function public.create_checkout_order(p_items jsonb) returns jsonb language sql security invoker set search_path = '' as $$ select private.create_checkout_order(p_items); $$; create or replace function public.record_checkout_payment(p_order_id uuid, p_provider text, p_provider_payment_id text) returns void language sql security invoker set search_path = '' as $$ select private.record_checkout_payment(p_order_id,p_provider,p_provider_payment_id); $$;  revoke all on function private.create_checkout_order(jsonb) from public, anon, authenticated, service_role; revoke all on function private.record_checkout_payment(uuid,text,text) from public, anon, authenticated, service_role; grant usage on schema private to authenticated; grant execute on function private.create_checkout_order(jsonb) to authenticated; grant execute on function private.record_checkout_payment(uuid,text,text) to authenticated; revoke all on function public.create_checkout_order(jsonb) from public, anon; revoke all on function public.record_checkout_payment(uuid,text,text) from public, anon; grant execute on function public.create_checkout_order(jsonb) to authenticated; grant execute on function public.record_checkout_payment(uuid,text,text) to authenticated; 